input.command:
node --version && node -e '
const starts=[];
const re=/\p{Nd}/u;
let prev=false;
for(let cp=0;cp<=0x10FFFF;cp++){
  if(cp>=0xD800&&cp<=0xDFFF){prev=false;continue;}
  const cur=re.test(String.fromCodePoint(cp));
  if(cur&&!prev)starts.push(cp);
  prev=cur;
}
// runs longer than 10 => adjacent blocks
const runs=[];
prev=false;let s=-1;
for(let cp=0;cp<=0x10FFFF;cp++){
  if(cp>=0xD800&&cp<=0xDFFF){if(prev){runs.push([s,cp-1]);prev=false;}continue;}
  const cur=re.test(String.fromCodePoint(cp));
  if(cur&&!prev){s=cp;}
  if(!cur&&prev){runs.push([s,cp-1]);}
  prev=cur;
}
console.log("total Nd runs:",runs.length);
console.log("runs longer than 10:",JSON.stringify(runs.filter(r=>r[1]-r[0]+1>10).map(r=>[r[0].toString(16),r[1].toString(16),r[1]-r[0]+1])));
// full zero-list
const zeros=[];
for(const [a,b] of runs){for(let z=a;z<=b;z+=10)zeros.push(z);}
console.log("num zero-points:",zeros.length);
console.log(JSON.stringify(zeros.map(z=>"0x"+z.toString(16).toUpperCase())).replace(/","/g,"\", \""));
'

